"""DERIVED COPY of tools/cavlc-embed/h264.py for the detectability step (do not edit the original).

Differences from the original (everything else is byte-identical; `diff` them):
  * residual_block() also decodes the levels and the scan position of every nonzero
    coefficient and appends one block record to SliceParser.blocks;
  * macroblock() appends one macroblock record to SliceParser.mbinfo (intra flag,
    Intra16x16 / chroma prediction mode, raw Intra4x4 mode syntax, transform_size_8x8_flag);
  * (this directory only, 2026-11-16) the VLC lookup tables and the coded_block_pattern mapping are built from
    cavlc_tables.py as generated by gen_tables_from_swift.py (code words keyed by the standard's syntax-element
    values); the lookup tables built from it are identical to the original's.
Original docstring follows.

H.264 CAVLC slice parser that records the sign bits of trailing-one coefficients.

Scope (anything else raises ParseError, never guesses):
  * 8-bit 4:2:0, frame_mbs_only, one slice group, entropy_coding_mode_flag = 0 (CAVLC)
  * I, P and B slices (Baseline: I/P; High with -coder 0: I/P/B), 4x4 and 8x8 transform
  * no data partitioning, no SP/SI, no MBAFF/PAFF, no FMO

The whole macroblock layer is parsed (mb_skip_run, mb_type, sub_mb_type, intra
pred modes, ref_idx, mvd, coded_block_pattern, mb_qp_delta, residual_block_cavlc with
the nC context from neighbouring blocks). Self-check: after each slice the reader
must sit exactly on the rbsp_stop_one_bit.

Syntax follows ITU-T H.264 clauses 7.3.2-7.3.5 and 9.2 (read from memory of the
standard and cross-validated against ffmpeg 8.1.1 decodes of the clips; see
docs/experiment-cavlc-embedding.md).
"""
from bitio import BitReader, ParseError
import cavlc_tables as T

SLICE_P, SLICE_B, SLICE_I = 0, 1, 2
SLICE_NAMES = {SLICE_P: "P", SLICE_B: "B", SLICE_I: "I"}

# sign-bit candidate kinds
K_LUMA, K_I16_DC, K_I16_AC, K_CDC, K_CAC = range(5)
KIND_NAMES = ["luma", "i16dc", "i16ac", "chroma_dc", "chroma_ac"]

# luma4x4BlkIdx -> (x, y) in 4x4 units
BLK_XY = [((b & 1) + 2 * ((b >> 2) & 1), ((b >> 1) & 1) + 2 * (b >> 3)) for b in range(16)]


# ---------------------------------------------------------------------------
# VLC lookup tables (built once from cavlc_tables)
# ---------------------------------------------------------------------------

def _build(codes, nbits):
    """codes: {value: code word as a bit string}. Return a flat list of (len << 8 | value) indexed by an nbits-wide peek."""
    tab = [0] * (1 << nbits)
    for val, word in codes.items():
        ln = len(word)
        lo = int(word, 2) << (nbits - ln)
        hi = lo + (1 << (nbits - ln))
        e = (ln << 8) | val
        tab[lo:hi] = [e] * (hi - lo)
    return tab


def _coeff_token(codes):
    """coeff_token decodes to total_coeff * 4 + trailing_ones (residual_block splits it again)."""
    return {tc * 4 + t1: word for (t1, tc), word in codes.items()}


_CT = [_build(_coeff_token(T.COEFF_TOKEN[i]), 16) for i in range(4)]
_CT_CDC = _build(_coeff_token(T.COEFF_TOKEN_CHROMA_DC), 8)
_TZ = [_build(T.TOTAL_ZEROS[i + 1], 9) for i in range(15)]
_TZ_CDC = [_build(T.TOTAL_ZEROS_CHROMA_DC[i + 1], 3) for i in range(3)]
_RUN = [_build(T.RUN_BEFORE[i + 1], 11) for i in range(7)]


# ---------------------------------------------------------------------------
# parameter sets
# ---------------------------------------------------------------------------

class SPS:
    pass


class PPS:
    pass


def _skip_scaling_list(br, size):
    last = 8
    nxt = 8
    for _ in range(size):
        if nxt != 0:
            nxt = (last + br.se() + 256) % 256
        last = last if nxt == 0 else nxt


def parse_sps(rbsp):
    br = BitReader(rbsp)
    s = SPS()
    s.profile_idc = br.u(8)
    s.constraint = br.u(8)
    s.level_idc = br.u(8)
    s.id = br.ue()
    s.chroma_format_idc = 1
    s.separate_colour_plane = 0
    s.bit_depth_luma = s.bit_depth_chroma = 8
    if s.profile_idc in (100, 110, 122, 244, 44, 83, 86, 118, 128, 138, 139, 134, 135):
        s.chroma_format_idc = br.ue()
        if s.chroma_format_idc == 3:
            s.separate_colour_plane = br.u(1)
        s.bit_depth_luma = 8 + br.ue()
        s.bit_depth_chroma = 8 + br.ue()
        br.u(1)  # qpprime_y_zero_transform_bypass_flag
        if br.u(1):  # seq_scaling_matrix_present_flag
            for i in range(8 if s.chroma_format_idc != 3 else 12):
                if br.u(1):
                    _skip_scaling_list(br, 16 if i < 6 else 64)
    if (s.chroma_format_idc, s.bit_depth_luma, s.bit_depth_chroma) != (1, 8, 8):
        raise ParseError("only 8-bit 4:2:0 is supported")
    s.log2_max_frame_num = br.ue() + 4
    s.poc_type = br.ue()
    s.log2_max_poc_lsb = 0
    s.delta_pic_order_always_zero = 0
    if s.poc_type == 0:
        s.log2_max_poc_lsb = br.ue() + 4
    elif s.poc_type == 1:
        s.delta_pic_order_always_zero = br.u(1)
        br.se()
        br.se()
        for _ in range(br.ue()):
            br.se()
    s.max_num_ref_frames = br.ue()
    br.u(1)  # gaps_in_frame_num_value_allowed_flag
    s.width_mbs = br.ue() + 1
    s.height_map_units = br.ue() + 1
    s.frame_mbs_only = br.u(1)
    if not s.frame_mbs_only:
        raise ParseError("interlaced/MBAFF is not supported")
    s.direct_8x8_inference = br.u(1)
    s.height_mbs = s.height_map_units
    s.crop = (0, 0, 0, 0)
    if br.u(1):
        s.crop = tuple(br.ue() for _ in range(4))
    return s


def parse_pps(rbsp):
    br = BitReader(rbsp)
    p = PPS()
    p.id = br.ue()
    p.sps_id = br.ue()
    p.entropy_coding_mode = br.u(1)
    p.bottom_field_pic_order_in_frame_present = br.u(1)
    if br.ue() != 0:
        raise ParseError("slice groups (FMO) are not supported")
    p.num_ref_idx_l0_default = br.ue() + 1
    p.num_ref_idx_l1_default = br.ue() + 1
    p.weighted_pred = br.u(1)
    p.weighted_bipred_idc = br.u(2)
    p.pic_init_qp = 26 + br.se()
    br.se()
    p.chroma_qp_index_offset = br.se()
    p.deblocking_filter_control_present = br.u(1)
    p.constrained_intra_pred = br.u(1)
    p.redundant_pic_cnt_present = br.u(1)
    p.transform_8x8_mode = 0
    # more_rbsp_data()
    last = len(rbsp) - 1
    while last >= 0 and rbsp[last] == 0:
        last -= 1
    b = rbsp[last]
    stop = last * 8 + 7 - ((b & -b).bit_length() - 1)
    if br.pos < stop:
        p.transform_8x8_mode = br.u(1)
        if br.u(1):  # pic_scaling_matrix_present_flag
            for i in range(6 + 2 * p.transform_8x8_mode):
                if br.u(1):
                    _skip_scaling_list(br, 16 if i < 6 else 64)
        br.se()  # second_chroma_qp_index_offset
    return p


# ---------------------------------------------------------------------------
# slice header
# ---------------------------------------------------------------------------

class SliceHeader:
    pass


def parse_slice_header(br, nal_unit_type, nal_ref_idc, spss, ppss):
    h = SliceHeader()
    h.first_mb = br.ue()
    st = br.ue()
    h.slice_type = st % 5
    if h.slice_type not in (SLICE_P, SLICE_B, SLICE_I):
        raise ParseError("SP/SI slices are not supported")
    pps_id = br.ue()
    if pps_id not in ppss:
        raise ParseError("unknown PPS %d" % pps_id)
    pps = ppss[pps_id]
    if pps.sps_id not in spss:
        raise ParseError("unknown SPS %d" % pps.sps_id)
    sps = spss[pps.sps_id]
    if pps.entropy_coding_mode:
        raise ParseError("CABAC stream (entropy_coding_mode_flag=1), not CAVLC")
    if sps.separate_colour_plane:
        raise ParseError("separate colour planes are not supported")
    h.pps, h.sps = pps, sps
    h.frame_num = br.u(sps.log2_max_frame_num)
    h.idr = nal_unit_type == 5
    if h.idr:
        h.idr_pic_id = br.ue()
    if sps.poc_type == 0:
        h.poc_lsb = br.u(sps.log2_max_poc_lsb)
        if pps.bottom_field_pic_order_in_frame_present:
            br.se()
    elif sps.poc_type == 1 and not sps.delta_pic_order_always_zero:
        br.se()
        if pps.bottom_field_pic_order_in_frame_present:
            br.se()
    if pps.redundant_pic_cnt_present:
        br.ue()
    if h.slice_type == SLICE_B:
        h.direct_spatial_mv_pred = br.u(1)
    h.num_ref_idx_l0 = pps.num_ref_idx_l0_default
    h.num_ref_idx_l1 = pps.num_ref_idx_l1_default
    if h.slice_type in (SLICE_P, SLICE_B):
        if br.u(1):
            h.num_ref_idx_l0 = br.ue() + 1
            if h.slice_type == SLICE_B:
                h.num_ref_idx_l1 = br.ue() + 1
    # ref_pic_list_modification
    lists = 0
    if h.slice_type in (SLICE_P, SLICE_B):
        lists = 1 if h.slice_type == SLICE_P else 2
    for _ in range(lists):
        if br.u(1):
            while True:
                idc = br.ue()
                if idc == 3:
                    break
                if idc > 5:
                    raise ParseError("bad modification_of_pic_nums_idc")
                br.ue()
    if (pps.weighted_pred and h.slice_type == SLICE_P) or \
            (pps.weighted_bipred_idc == 1 and h.slice_type == SLICE_B):
        br.ue()  # luma_log2_weight_denom
        br.ue()  # chroma_log2_weight_denom
        for n in ([h.num_ref_idx_l0] + ([h.num_ref_idx_l1] if h.slice_type == SLICE_B else [])):
            for _ in range(n):
                if br.u(1):
                    br.se()
                    br.se()
                if br.u(1):
                    for _ in range(2):
                        br.se()
                        br.se()
    if nal_ref_idc != 0:
        if h.idr:
            br.u(1)
            br.u(1)
        elif br.u(1):
            while True:
                op = br.ue()
                if op == 0:
                    break
                if op in (1, 3):
                    br.ue()
                if op == 2:
                    br.ue()
                if op in (3, 6):
                    br.ue()
                if op == 4:
                    br.ue()
                if op > 6:
                    raise ParseError("bad memory_management_control_operation")
    h.slice_qp_delta = br.se()
    if pps.deblocking_filter_control_present:
        if br.ue() != 1:
            br.se()
            br.se()
    return h


# ---------------------------------------------------------------------------
# macroblock tables
# ---------------------------------------------------------------------------

# P mb_type 0..4 -> number of partitions (0: 16x16, 1: 16x8, 2: 8x16, 3/4: 8x8)
_P_PARTS = [1, 2, 2, 4, 4]
# P sub_mb_type -> number of sub-partitions
_P_SUB_PARTS = [1, 2, 2, 4]
# B mb_type 1..21: (nparts, uses per part)
_L0, _L1, _BI = (True, False), (False, True), (True, True)
_B_PAIRS = [(_L0, _L0), (_L1, _L1), (_L0, _L1), (_L1, _L0), (_L0, _BI), (_L1, _BI),
            (_BI, _L0), (_BI, _L1), (_BI, _BI)]
_B_16 = {1: [_L0], 2: [_L1], 3: [_BI]}
for _t in range(4, 22):
    _B_16[_t] = list(_B_PAIRS[(_t - 4) // 2])
# B sub_mb_type: (uses_l0, uses_l1, nparts, direct)
_B_SUB = [(False, False, 4, True), (True, False, 1, False), (False, True, 1, False), (True, True, 1, False),
          (True, False, 2, False), (True, False, 2, False), (False, True, 2, False), (False, True, 2, False),
          (True, True, 2, False), (True, True, 2, False), (True, False, 4, False), (False, True, 4, False),
          (True, True, 4, False)]


class SliceData:
    """Result of parsing one slice NAL."""
    __slots__ = ("header", "signs", "mbs", "end_ok", "first_mb", "n_mbs", "intra_mbs", "n_pcm", "blocks", "mbinfo")


class PictureState:
    """Per-picture neighbour context shared by the slices of one picture."""

    def __init__(self, sps):
        self.w = sps.width_mbs
        self.h = sps.height_mbs
        n = self.w * self.h
        self.nnz_y = [0] * (n * 16)
        self.nnz_cb = [0] * (n * 4)
        self.nnz_cr = [0] * (n * 4)
        self.slice_id = [-1] * n
        self.n = n


class SliceParser:
    def __init__(self, rbsp, hdr, br, pic, slice_id):
        self.br = br
        self.hdr = hdr
        self.pic = pic
        self.sid = slice_id
        self.pps = hdr.pps
        self.sps = hdr.sps
        self.signs = []  # (rbsp_bit_pos, mb_addr, kind)
        self.intra_mbs = set()  # addresses of intra macroblocks (they spread changes by intra prediction)
        self.blocks = []  # block records, see residual_block
        self.mbinfo = {}  # addr -> (intra, i16_pred_mode or -1, chroma_pred_mode or -1, i4_modes tuple, t8)
        self._cur_blk = (0, 0, 0)
        self._mbi = None
        # position of rbsp_stop_one_bit
        last = len(rbsp) - 1
        while last >= 0 and rbsp[last] == 0:
            last -= 1
        if last < 0:
            raise ParseError("empty RBSP")
        b = rbsp[last]
        self.stop = last * 8 + 7 - ((b & -b).bit_length() - 1)
        self.cur_addr = 0
        self.n_mbs = 0
        self.n_pcm = 0

    # -- neighbour context -------------------------------------------------
    def _nc(self, nnz, addr, bx, by, bw):
        """nC for block (bx, by) of an MB whose blocks form a bw x bw grid."""
        pic = self.pic
        mbw = pic.w
        sid = self.sid
        sl = pic.slice_id
        if bx > 0:
            na = nnz[addr * bw * bw + by * bw + bx - 1]
            av_a = True
        elif addr % mbw > 0 and sl[addr - 1] == sid:
            na = nnz[(addr - 1) * bw * bw + by * bw + bw - 1]
            av_a = True
        else:
            na = 0
            av_a = False
        if by > 0:
            nb = nnz[addr * bw * bw + (by - 1) * bw + bx]
            av_b = True
        elif addr >= mbw and sl[addr - mbw] == sid:
            nb = nnz[(addr - mbw) * bw * bw + (bw - 1) * bw + bx]
            av_b = True
        else:
            nb = 0
            av_b = False
        if av_a and av_b:
            return (na + nb + 1) >> 1
        if av_a:
            return na
        if av_b:
            return nb
        return 0

    # -- residual_block_cavlc ---------------------------------------------
    def residual_block(self, nc, max_coeff, kind):
        """Parse one residual block; returns total_coeff."""
        br = self.br
        if nc == -1:
            e = _CT_CDC[br.peek(8)]
            if e == 0:
                raise ParseError("bad chroma DC coeff_token")
        else:
            tab = 0 if nc < 2 else 1 if nc < 4 else 2 if nc < 8 else 3
            e = _CT[tab][br.peek(16)]
            if e == 0:
                raise ParseError("bad coeff_token")
        br.pos += e >> 8
        v = e & 0xFF
        total = v >> 2
        t1 = v & 3
        if total == 0:
            return 0
        if total > max_coeff:
            raise ParseError("total_coeff %d > maxNumCoeff %d" % (total, max_coeff))
        addr = self.cur_addr
        signs = self.signs
        levels = []
        t1pos = []
        for _ in range(t1):
            signs.append((br.pos, addr, kind))
            t1pos.append(br.pos)
            levels.append(-1 if br.d[br.pos >> 3] & (0x80 >> (br.pos & 7)) else 1)
            br.pos += 1
        suffix_len = 1 if (total > 10 and t1 < 3) else 0
        for i in range(t1, total):
            # level_prefix
            lp = 0
            while br.u(1) == 0:
                lp += 1
                if lp > 32:
                    raise ParseError("level_prefix too long")
            level_code = min(15, lp) << suffix_len
            if suffix_len > 0 or lp >= 14:
                if lp == 14 and suffix_len == 0:
                    size = 4
                elif lp >= 15:
                    size = lp - 3
                else:
                    size = suffix_len
                if size:
                    level_code += br.u(size)
            if lp >= 15 and suffix_len == 0:
                level_code += 15
            if lp >= 16:
                level_code += (1 << (lp - 3)) - 4096
            if i == t1 and t1 < 3:
                level_code += 2
            level = (level_code + 2) >> 1 if level_code % 2 == 0 else (-level_code - 1) >> 1
            levels.append(level)
            if suffix_len == 0:
                suffix_len = 1
            if abs(level) > (3 << (suffix_len - 1)) and suffix_len < 6:
                suffix_len += 1
        # total_zeros
        runs = [0] * total
        if total < max_coeff:
            if max_coeff == 4:
                e = _TZ_CDC[total - 1][br.peek(3)]
            else:
                e = _TZ[total - 1][br.peek(9)]
            if e == 0:
                raise ParseError("bad total_zeros")
            br.pos += e >> 8
            zeros_left = e & 0xFF
            # run_before for all but the last coefficient
            for j in range(total - 1):
                if zeros_left <= 0:
                    break
                e = _RUN[min(zeros_left, 7) - 1][br.peek(11)]
                if e == 0:
                    raise ParseError("bad run_before")
                br.pos += e >> 8
                runs[j] = e & 0xFF
                zeros_left -= e & 0xFF
                if zeros_left < 0:
                    raise ParseError("run_before exceeds zeros_left")
            runs[total - 1] = zeros_left
        # scan positions: levels[0] is the highest-frequency coefficient
        pos = [0] * total
        cn = -1
        for j in range(total - 1, -1, -1):
            cn += runs[j] + 1
            pos[j] = cn
        self.blocks.append((addr, kind, self._cur_blk, nc, total, t1, 1 if max_coeff == 15 else 0, levels, pos, t1pos))
        return total

    # -- residual ----------------------------------------------------------
    def residual(self, addr, i16, cbp_luma, cbp_chroma):
        pic = self.pic
        nnz_y = pic.nnz_y
        if i16:
            nc = self._nc(nnz_y, addr, 0, 0, 4)
            self._cur_blk = (0, 0, 0)
            self.residual_block(nc, 16, K_I16_DC)
        for i8 in range(4):
            if not (cbp_luma >> i8) & 1:
                continue
            for i4 in range(4):
                bx, by = BLK_XY[i8 * 4 + i4]
                nc = self._nc(nnz_y, addr, bx, by, 4)
                self._cur_blk = (0, bx, by)
                if i16:
                    tc = self.residual_block(nc, 15, K_I16_AC)
                else:
                    tc = self.residual_block(nc, 16, K_LUMA)
                nnz_y[addr * 16 + by * 4 + bx] = tc
        if cbp_chroma & 3:
            self._cur_blk = (1, 0, 0)
            self.residual_block(-1, 4, K_CDC)
            self._cur_blk = (2, 0, 0)
            self.residual_block(-1, 4, K_CDC)
        if cbp_chroma & 2:
            for plane, nnz in ((1, pic.nnz_cb), (2, pic.nnz_cr)):
                for blk in range(4):
                    bx, by = blk & 1, blk >> 1
                    nc = self._nc(nnz, addr, bx, by, 2)
                    self._cur_blk = (plane, bx, by)
                    nnz[addr * 4 + by * 2 + bx] = self.residual_block(nc, 15, K_CAC)

    # -- macroblock layer --------------------------------------------------
    def macroblock(self, addr):
        br = self.br
        hdr = self.hdr
        pps = self.pps
        st = hdr.slice_type
        self.cur_addr = addr
        mb_type = br.ue()
        # normalise to intra mb_type or inter description
        intra = False
        if st == SLICE_I:
            intra = True
            it = mb_type
        elif st == SLICE_P:
            if mb_type >= 5:
                intra, it = True, mb_type - 5
        else:
            if mb_type >= 23:
                intra, it = True, mb_type - 23
        pic = self.pic
        i4m = []
        t8 = 0
        i16mode = -1
        cmode = -1
        if intra:
            self.intra_mbs.add(addr)
            if it > 25:
                raise ParseError("bad intra mb_type")
            if it == 25:  # I_PCM
                self.n_pcm += 1
                br.align()
                br.pos += 8 * (256 + 128)
                if br.pos > br.nbits:
                    raise ParseError("I_PCM runs past end")
                for k in range(16):
                    pic.nnz_y[addr * 16 + k] = 16
                for k in range(4):
                    pic.nnz_cb[addr * 4 + k] = 16
                    pic.nnz_cr[addr * 4 + k] = 16
                self.mbinfo[addr] = (1, -1, -1, (), 0)
                return
            i16 = it != 0
            if not i16:
                t8 = br.u(1) if pps.transform_8x8_mode else 0
                for _ in range(4 if t8 else 16):
                    if not br.u(1):
                        i4m.append(br.u(3))
                    else:
                        i4m.append(-1)  # predicted mode used (no rem syntax)
            else:
                t = it - 1
                i16mode = t % 4
                cbp_chroma = (t // 4) % 3
                cbp_luma = 15 if it >= 13 else 0
            cmode = br.ue()  # intra_chroma_pred_mode
            if not i16:
                code = br.ue()
                if code > 47:
                    raise ParseError("bad coded_block_pattern")
                cbp = T.CODED_BLOCK_PATTERN[code][0]
                cbp_luma, cbp_chroma = cbp & 15, cbp >> 4
        else:
            no_sub_lt8 = True
            direct16 = False
            if st == SLICE_P:
                if mb_type > 4:
                    raise ParseError("bad P mb_type")
                nparts = _P_PARTS[mb_type]
                if nparts == 4:
                    subs = [br.ue() for _ in range(4)]
                    if any(s > 3 for s in subs):
                        raise ParseError("bad P sub_mb_type")
                    n0 = hdr.num_ref_idx_l0 - 1
                    if n0 > 0 and mb_type != 4:
                        for _ in range(4):
                            br.te(n0)
                    for s in subs:
                        if _P_SUB_PARTS[s] > 1:
                            no_sub_lt8 = False
                        for _ in range(_P_SUB_PARTS[s]):
                            br.se()
                            br.se()
                else:
                    n0 = hdr.num_ref_idx_l0 - 1
                    if n0 > 0:
                        for _ in range(nparts):
                            br.te(n0)
                    for _ in range(nparts):
                        br.se()
                        br.se()
            else:
                n0 = hdr.num_ref_idx_l0 - 1
                n1 = hdr.num_ref_idx_l1 - 1
                if mb_type == 0:
                    direct16 = True
                elif mb_type == 22:
                    subs = [br.ue() for _ in range(4)]
                    if any(s > 12 for s in subs):
                        raise ParseError("bad B sub_mb_type")
                    info = [_B_SUB[s] for s in subs]
                    for u0, u1, npart, direct in info:
                        if direct:
                            if not hdr.sps.direct_8x8_inference:
                                no_sub_lt8 = False
                        elif npart > 1:
                            no_sub_lt8 = False
                    if n0 > 0:
                        for u0, u1, npart, direct in info:
                            if not direct and u0:
                                br.te(n0)
                    if n1 > 0:
                        for u0, u1, npart, direct in info:
                            if not direct and u1:
                                br.te(n1)
                    for u0, u1, npart, direct in info:
                        if not direct and u0:
                            for _ in range(npart):
                                br.se()
                                br.se()
                    for u0, u1, npart, direct in info:
                        if not direct and u1:
                            for _ in range(npart):
                                br.se()
                                br.se()
                elif 1 <= mb_type <= 21:
                    parts = _B_16[mb_type]
                    if n0 > 0:
                        for u0, u1 in parts:
                            if u0:
                                br.te(n0)
                    if n1 > 0:
                        for u0, u1 in parts:
                            if u1:
                                br.te(n1)
                    for u0, u1 in parts:
                        if u0:
                            br.se()
                            br.se()
                    for u0, u1 in parts:
                        if u1:
                            br.se()
                            br.se()
                else:
                    raise ParseError("bad B mb_type")
            code = br.ue()
            if code > 47:
                raise ParseError("bad coded_block_pattern")
            cbp = T.CODED_BLOCK_PATTERN[code][1]
            cbp_luma, cbp_chroma = cbp & 15, cbp >> 4
            i16 = False
            if cbp_luma > 0 and pps.transform_8x8_mode and no_sub_lt8 and \
                    (not direct16 or hdr.sps.direct_8x8_inference):
                t8 = br.u(1)  # transform_size_8x8_flag (no effect on CAVLC syntax)
        self.mbinfo[addr] = (1 if intra else 0, i16mode, cmode, tuple(i4m), t8)
        if cbp_luma > 0 or cbp_chroma > 0 or i16:
            br.se()  # mb_qp_delta
            self.residual(addr, i16, cbp_luma, cbp_chroma)

    # -- slice data --------------------------------------------------------
    def run(self, first_mb):
        br = self.br
        pic = self.pic
        addr = first_mb
        total = pic.n
        sl = pic.slice_id
        inter = self.hdr.slice_type != SLICE_I
        more = True
        n = 0
        while True:
            if inter:
                run = br.ue()
                if run:
                    if addr + run > total:
                        raise ParseError("mb_skip_run past picture end")
                    for k in range(run):
                        sl[addr + k] = self.sid
                    addr += run
                    n += run
                    more = br.pos < self.stop
            if more:
                if addr >= total:
                    raise ParseError("macroblock past picture end")
                sl[addr] = self.sid
                self.macroblock(addr)
                addr += 1
                n += 1
            more = br.pos < self.stop
            if not more:
                break
        self.n_mbs = n
        if br.pos != self.stop:
            raise ParseError("slice does not end on the stop bit (%d != %d)" % (br.pos, self.stop))
        return addr


def parse_slice(rbsp, nal_unit_type, nal_ref_idc, spss, ppss, pic_holder, slice_id):
    """Parse one slice RBSP (header already past the NAL header byte).

    pic_holder is a dict carrying 'pic' (PictureState) across slices of a picture.
    Returns SliceData.
    """
    br = BitReader(rbsp)
    hdr = parse_slice_header(br, nal_unit_type, nal_ref_idc, spss, ppss)
    hdr.nal_ref_idc = nal_ref_idc
    hdr.nal_unit_type = nal_unit_type
    sps = hdr.sps
    if hdr.first_mb == 0 or pic_holder.get("pic") is None:
        pic_holder["pic"] = PictureState(sps)
        pic_holder["mbs_done"] = 0
    pic = pic_holder["pic"]
    sp = SliceParser(rbsp, hdr, br, pic, slice_id)
    sp.run(hdr.first_mb)
    pic_holder["mbs_done"] += sp.n_mbs
    d = SliceData()
    d.header = hdr
    d.signs = sp.signs
    d.blocks = sp.blocks
    d.mbinfo = sp.mbinfo
    d.intra_mbs = sp.intra_mbs
    d.n_pcm = sp.n_pcm
    d.first_mb = hdr.first_mb
    d.n_mbs = sp.n_mbs
    d.end_ok = True
    d.mbs = pic_holder["mbs_done"]
    return d
